/// <summary>
/// SysOperation controller for scheduling and executing the <c>UTCSFCustomerPushBatchService</c>.
/// </summary>
public class UTCSFCustomerPushBatchController extends SysOperationServiceController
{
}

Method.Source:
public void new()
{
    super(
        classStr(UTCSFCustomerPushBatchService),
        methodStr(UTCSFCustomerPushBatchService, processQueue),
        SysOperationExecutionMode::Synchronous);
}

public static UTCSFCustomerPushBatchController construct(
    SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    UTCSFCustomerPushBatchController controller = new UTCSFCustomerPushBatchController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

protected ClassDescription defaultCaption()
{
    return 'UTC Salesforce Real-Time Customer Push Queue Processor';
}

public static void main(Args _args)
{
    UTCSFCustomerPushBatchController controller = UTCSFCustomerPushBatchController::construct();
    controller.parmArgs(_args);
    controller.startOperation();
}
